import type { AssetPack } from '../../src/game/assets/asset-pack';
import { DEFAULT_SETTINGS } from '../../src/game/core/constants';
import { GameRenderer } from '../../src/game/render/pixi-renderer';
import { World } from '../../src/game/simulation/world';
import { PlaythroughPilot } from './pilot';
import { showWinScreen } from '../fixtures/screens';

/** Accelerated control-only session with the exact browser collision providers used by GameViewport. */
export async function runPlaythrough(
  pack: AssetPack,
  host: HTMLElement,
  progress: (text: string) => void,
) {
  const seed = 17,
    world = new World([], [], seed),
    pilot = new PlaythroughPilot();
  world.hitTest = pack.hitTest;
  world.hitPart = pack.hitPart;
  world.hitProjectile = pack.hitProjectile;
  world.protectionRadius = pack.protectionRadius;
  world.displayWidth = pack.tankDisplayWidth;
  world.projectileBounds = (bullet) =>
    pack.projectileBounds(
      bullet,
      bullet.kind === 'turret'
        ? world.allTanks().find((tank) => tank.uid === bullet.owner)
        : undefined,
    );
  const renderer = new GameRenderer(pack),
    settings = { ...DEFAULT_SETTINGS, quality: 'low' as const };
  await renderer.init(host, settings);
  const sheet = document.createElement('canvas');
  sheet.id = 'run-history';
  sheet.width = 550;
  sheet.height = 1250;
  const ctx = sheet.getContext('2d')!;
  ctx.fillStyle = '#0b3c5a';
  ctx.fillRect(0, 0, sheet.width, sheet.height);
  const milestones: {
    label: string;
    frame: number;
    level: number;
    life: number;
    tank: string;
    field: string;
  }[] = [];
  let frame = 0,
    digest = 2166136261,
    choices = 0,
    bossSeen = false,
    downGrades = 0,
    previousLevel = 0;
  const capture = (label: string) => {
    renderer.draw(world, settings);
    const index = milestones.length,
      x = (index % 2) * 275,
      y = Math.floor(index / 2) * 250;
    ctx.drawImage(renderer.app.canvas, x, y, 275, 225);
    ctx.fillStyle = '#e7f7ff';
    ctx.font = '11px Arial';
    ctx.fillText(`${label} · f${frame} · HP${world.player.life}`, x + 8, y + 243);
    milestones.push({
      label,
      frame,
      level: world.progression.level,
      life: world.player.life,
      tank: world.player.design.id,
      field: `${world.field.col},${world.field.row}`,
    });
  };
  capture('Fresh game');
  try {
    for (; frame < 200000 && world.mode !== 'won'; frame++) {
      const input = pilot.input(world);
      if (pilot.upgrades.length > choices) {
        choices = pilot.upgrades.length;
        if (milestones.length < 7) capture(`Upgrade${world.progression.level}`);
      }
      // Replay fingerprint includes every normal input; it is evidence, not a gameplay mutation.
      for (const value of [
        Number(input.up),
        Number(input.down),
        Number(input.left),
        Number(input.right),
        Number(input.fire),
        Number(input.secondary),
        Math.round(input.aim.x * 100),
        Math.round(input.aim.y * 100),
      ])
        digest = Math.imul(digest ^ value, 16777619);
      world.step(input);
      world.drainEvents();
      if (world.progression.level < previousLevel) downGrades++;
      previousLevel = world.progression.level;
      if (world.bossTriggered && !bossSeen) {
        bossSeen = true;
        capture('Boss field generated');
      }
      if (frame % 1000 === 0) {
        progress(
          `Run · frame${frame} · level${world.progression.level} · life${world.player.life} · ${world.stats.kills} kills`,
        );
      }
      // The real viewport yields between stage callbacks. Keep accelerated jobs
      // short too: WeakRef.deref retains targets until synchronous work ends, so
      // 1,000-step jobs otherwise keep expired clip trees ticking for that batch.
      // This changes no input, simulated milliseconds, frame cap or test budget.
      if (frame % 50 === 0) await new Promise<void>((resolve) => setTimeout(resolve, 0));
    }
    if (world.mode !== 'won')
      throw new Error(
        `Pilot did not win after${frame} frames: level${world.progression.level}, life${world.player.life}, boss${world.bossTriggered}/${world.bossDefeated}`,
      );
    capture('Boss defeated · won');
    const panel = document.createElement('div');
    panel.style.position = 'absolute';
    panel.style.inset = '0';
    host.appendChild(panel);
    const unmount = showWinScreen(
      pack,
      panel,
      (action) => (host.dataset.winAction = action),
      false,
    );
    sheet.style.width = '550px';
    sheet.style.height = '1250px';
    host.after(sheet);
    const proof = {
      seed,
      assets: pack.mode,
      frames: frame,
      inputDigest: digest >>> 0,
      mode: world.mode,
      bossTriggered: world.bossTriggered,
      bossDefeated: world.bossDefeated,
      badge: world.achievements.has('Boss Badge'),
      upgrades: pilot.upgrades,
      helpClosed: pilot.helpClosed,
      downGrades,
      stats: { ...world.stats },
      milestones,
    };
    return {
      renderer,
      proof,
      unmount: () => {
        unmount();
        panel.remove();
        sheet.remove();
      },
    };
  } catch (error) {
    renderer.destroy();
    throw error;
  }
}
import { FIELD_RADIUS, STAGE } from '../../src/game/core/constants';
import { direction, distance } from '../../src/game/core/math';
import type { InputFrame, TankDesign, Vec } from '../../src/game/core/types';
import { WEAPONS } from '../../src/game/data/weapons';
import { World, emptyInput } from '../../src/game/simulation/world';

/** Test pilot observes state but can only issue ordinary controls and offered upgrade choices. */
export class PlaythroughPilot {
  private route?: Vec;
  private fieldKey = '';
  upgrades: { level: number; id: string; classId: number }[] = [];
  helpClosed = 0;

  private choose(offers: TankDesign[]) {
    const score = (tank: TankDesign) => {
      const damage = tank.parts.reduce((total, part) => {
        const gun = WEAPONS[part.type];
        return (
          total +
          (gun
            ? (gun.damage * (gun.parallel ?? gun.angles?.length ?? 1)) / Math.max(1, gun.rate)
            : 0)
        );
      }, 0);
      return (
        damage +
        (tank.parts.some((p) => p.type === 3010) ? 0.4 : 0) -
        Math.max(0, tank.classId - 3) * 2
      );
    };
    return [...offers].sort((a, b) => score(b) - score(a))[0];
  }

  private nextExit(world: World): Vec {
    const queue = [{ col: world.field.col, row: world.field.row, first: { x: 0, y: 0 } }];
    const seen = new Set<string>();
    for (let index = 0; index < queue.length; index++) {
      const cell = queue[index];
      const options = [
        { x: 1, y: 0 },
        { x: 0, y: 1 },
        { x: -1, y: 0 },
        { x: 0, y: -1 },
      ].sort(
        (a, b) =>
          Math.hypot(cell.col + a.x, cell.row + a.y) - Math.hypot(cell.col + b.x, cell.row + b.y),
      );
      for (const step of options) {
        const col = cell.col + step.x,
          row = cell.row + step.y,
          key = `${col},${row}`;
        const first = index === 0 ? step : cell.first;
        if (!world.fields.has(key)) return first;
        if (seen.has(key) || !world.fields.get(key)!.cleared) continue;
        seen.add(key);
        queue.push({ col, row, first });
      }
    }
    throw new Error('No reachable unexplored field');
  }

  input(world: World): InputFrame {
    if (world.mode === 'upgrade') {
      const selected = this.choose(world.offers);
      this.upgrades.push({
        level: world.progression.level,
        id: selected.id,
        classId: selected.classId,
      });
      world.selectUpgrade(selected);
    }
    if (world.mode === 'secondary-help') {
      this.helpClosed++;
      world.closeSecondaryHelp();
    }
    const input = emptyInput(),
      player = world.player;
    if (world.mode !== 'playing') return input;
    const targets = world.field.enemies.filter((enemy) => !enemy.dead);
    const target = targets.sort((a, b) => distance(player, a) - distance(player, b))[0];
    let movement = { x: 0, y: 0 };
    const radius = FIELD_RADIUS * world.field.scale;
    if (target) {
      this.route = undefined;
      const dx = target.x - player.x,
        dy = target.y - player.y,
        gap = Math.hypot(dx, dy) || 1;
      const approach = Math.max(-1, Math.min(1, (gap - 200) / 90));
      movement = {
        x: (dx / gap) * approach - (dy / gap) * 0.8,
        y: (dy / gap) * approach + (dx / gap) * 0.8,
      };
      for (const other of targets) {
        const d = distance(player, other) || 1;
        if (d < 120) {
          movement.x += (((player.x - other.x) / d) * (120 - d)) / 35;
          movement.y += (((player.y - other.y) / d) * (120 - d)) / 35;
        }
      }
      const lead = direction(target.rotation, target.design.speed * Math.min(30, gap / 10));
      input.aim = { x: STAGE.cx + dx + lead.x, y: STAGE.cy + dy + lead.y };
      input.fire = input.secondary = true;
      const radial = Math.hypot(player.x, player.y);
      if (radial > radius - 90) {
        movement.x -= ((player.x / radial) * (radial - radius + 90)) / 25;
        movement.y -= ((player.y / radial) * (radial - radius + 90)) / 25;
      }
    } else if (world.pickups.length && world.field.cleared) {
      // Let forced rewards arrive before departure. Releasing the keys alone
      // coasts through the wall and can open first-secondary help mid-crossing.
      // Its source Close selects ordinary mode while movement remains disabled.
      const gap = Math.hypot(player.x, player.y) || 1;
      movement = { x: -player.x / gap, y: -player.y / gap };
    } else if (!world.pickups.length && world.field.cleared) {
      const key = `${world.field.col},${world.field.row}`;
      if (!this.route || this.fieldKey !== key) {
        this.route = this.nextExit(world);
        this.fieldKey = key;
      }
      movement = {
        x: this.route.x * (radius + 70) - player.x,
        y: this.route.y * (radius + 70) - player.y,
      };
      const d = Math.hypot(movement.x, movement.y) || 1;
      movement.x /= d;
      movement.y /= d;
    }
    for (const bullet of world.bullets) {
      if (!bullet.enemy || bullet.dead || distance(player, bullet) > 220) continue;
      const velocity = bullet.motion ?? direction(bullet.angle, bullet.speed);
      const vx = velocity.x - player.velocity.x,
        vy = velocity.y - player.velocity.y;
      const dx = player.x - bullet.x,
        dy = player.y - bullet.y;
      const t = Math.max(0, Math.min(15, (dx * vx + dy * vy) / (vx * vx + vy * vy || 1)));
      const near = { x: dx - vx * t, y: dy - vy * t },
        gap = Math.hypot(near.x, near.y) || 1;
      const danger = player.radius + 12;
      if (gap < danger) {
        movement.x += (((near.x / gap) * (danger - gap)) / danger) * 3;
        movement.y += (((near.y / gap) * (danger - gap)) / danger) * 3;
      }
    }
    // Hold the battle inside the field even when a dense volley overwhelms avoidance.
    // Source deliberately suppresses the win screen when completion happens during transit.
    const radial = Math.hypot(player.x, player.y);
    if ((target || !world.field.cleared) && radial > radius - 50)
      movement = { x: -player.x / radial, y: -player.y / radial };
    input.left = movement.x < -0.2;
    input.right = movement.x > 0.2;
    input.up = movement.y < -0.2;
    input.down = movement.y > 0.2;
    return input;
  }
}

